using System.Numerics;
using LiveryStudio.Core;

internal static class PatternChecks
{
    public static void Run(string temp,Action<bool,string> check,Action<Action,string> reject)
    {
        var options=new PatternArtworkOptions{ColorA="#FF0000",ColorB="#0000FF",Aspect=2,Resolution=512};
        foreach(var kind in Enum.GetValues<PatternKind>()){var image=PatternArtwork.Render(options with {Kind=kind},64);check(image.Width==64&&image.Height==32&&image.Pixels.Length==64*32*4&&image.Pixels.Where((_,i)=>i%4==3).All(a=>a==255),"Generated pattern has valid dimensions and opaque coverage: "+kind);}
        var gradient=PatternArtwork.Render(options,64);int At(int x,int y)=>(y*gradient.Width+x)*4;
        check(gradient.Pixels[At(0,16)]>250&&gradient.Pixels[At(0,16)+2]<5&&gradient.Pixels[At(63,16)]<5&&gradient.Pixels[At(63,16)+2]>250,"Linear gradient reaches both chosen endpoint colors");
        check(gradient.Pixels[At(32,16)]>175&&gradient.Pixels[At(32,16)]<195&&gradient.Pixels[At(32,16)+2]>175,"Gradient colors interpolate in linear light before display encoding");
        var faded=PatternArtwork.Render(options with {AlphaB=0},64);check(faded.Pixels[At(0,16)+3]>250&&faded.Pixels[At(63,16)+3]<5&&faded.Pixels[At(32,16)+3]>100&&faded.Pixels[At(32,16)+3]<150,"Fade-to-paint gradients retain partial alpha rather than baking a black background");
        check(Enumerable.Range(0,faded.Width*faded.Height).Where(i=>faded.Pixels[i*4+3]>0).All(i=>faded.Pixels[i*4]==255&&faded.Pixels[i*4+1]==0&&faded.Pixels[i*4+2]==0),"Transparent color transitions preserve straight-alpha color without dark fringes");
        var edge=PatternArtwork.Render(options with {EdgeFade=.25f},64);check(edge.Pixels[At(32,0)+3]<10&&edge.Pixels[At(32,16)+3]>250,"Edge softening fades the border while retaining the interior");
        var radial=PatternArtwork.Render(options with {Kind=PatternKind.RadialGradient,CenterX=.25f,CenterY=.5f,Radius=.4f},64);check(radial.Pixels[At(16,16)]>250&&radial.Pixels[At(63,16)+2]>250,"Radial gradient respects an offset center and radius");
        var checkerOptions=options with {Kind=PatternKind.Checker,ColorA="#FFFFFF",ColorB="#000000",Repeats=4};var checker=PatternArtwork.Render(checkerOptions,64);check(checker.Pixels[At(2,2)]==255&&checker.Pixels[At(10,2)]==0&&checker.Pixels[At(10,10)]==255,"Checker pattern alternates both axes with square cells");
        var rotated=PatternArtwork.Render(options with {Kind=PatternKind.Stripes,Angle=22,Repeats=9},64);check(Enumerable.Range(0,rotated.Width*rotated.Height).Any(i=>rotated.Pixels[i*4]>0&&rotated.Pixels[i*4+2]>0),"Supersampling smooths diagonal pattern edges");
        var dots=PatternArtwork.Render(options with {Kind=PatternKind.Dots,AlphaB=0,Repeats=6},64);check(dots.Pixels.Where((_,i)=>i%4==3).Any(a=>a==0)&&dots.Pixels.Where((_,i)=>i%4==3).Any(a=>a==255),"Dot patterns can cut through to the underlying paint");
        var weave=PatternArtwork.Render(options with {Kind=PatternKind.CarbonWeave,ColorA="#101010",ColorB="#909090"},256);check(weave.Pixels.Where((_,i)=>i%4==0).Distinct().Count()>20,"Carbon weave generates fibers and curved bands rather than a flat checker");
        check(!checker.Pixels.SequenceEqual(PatternArtwork.Render(checkerOptions with {Phase=.35f},64).Pixels),"Pattern phase shifts the design without changing its palette");
        var workspace=Path.Combine(temp,"pattern-library");var path=PatternArtwork.Generate(options,workspace);var before=File.ReadAllBytes(path);var again=PatternArtwork.Generate(options with {},workspace);check(path==again&&File.ReadAllBytes(path).SequenceEqual(before)&&PatternArtwork.ReadMetadata(path)==options,"Identical pattern recipes reuse a reproducible asset and metadata");
        var changed=PatternArtwork.Generate(options with {Angle=45},workspace);check(path!=changed&&File.ReadAllBytes(path).SequenceEqual(before),"Editing a recipe creates a new asset without changing prior history pixels");
        File.WriteAllBytes(path,[1,2,3]);var repaired=PatternArtwork.Generate(options,workspace);check(repaired!=path&&File.ReadAllBytes(path).SequenceEqual(new byte[]{1,2,3})&&FinishMaps.Read(repaired).Width==512,"Regeneration preserves an externally modified asset and writes an independent replacement");
        var blank=Path.Combine(temp,"pattern-base.tga");FinishMaps.WriteTga(new(64,64,new byte[64*64*4]),blank);var layer=new PaintLayer{Name="Gradient",Asset=repaired,PatternArtwork=options with {},Samples=[new(Vector3.Zero,Vector3.UnitZ,Vector3.UnitX,Vector3.UnitY,1,.5f)],Rotation=17,ScaleX=1.4f,Gloss=.2f,Metalness=.6f};
        var doc=new LayerDocument{BaseAlbedo=blank,BaseStructure=blank};doc.Commit("Pattern",l=>l.Add(layer));check(doc.Version==4&&doc.Layers[0].PatternArtwork==options,"Editable patterns upgrade the editor format to version 4");doc.Commit("Changed pattern",l=>{l[0].PatternArtwork=options with {Angle=45};l[0].Asset=changed;});check(doc.Undo()&&doc.Layers[0].PatternArtwork==options&&doc.Redo()&&doc.Layers[0].PatternArtwork?.Angle==45,"Pattern settings and assets participate in persistent undo and redo");
        var editor=Path.Combine(temp,"pattern-editor.json");doc.Save(editor);var bundle=Path.Combine(temp,"pattern.flproject");ProjectBundle.Save(new(){Albedo=blank,Structure=blank,EditorFile=editor},bundle);File.Delete(changed);var restored=ProjectBundle.Open(bundle,Path.Combine(temp,"pattern-restored"));var restoredDoc=LayerDocument.Read(restored.EditorFile);var restoredLayer=restoredDoc.Layers[0];check(restoredDoc.Version==4&&restoredLayer.PatternArtwork?.Angle==45&&FinishMaps.Read(restoredLayer.Asset).Width==512&&restoredLayer.Rotation==17&&restoredLayer.ScaleX==1.4f&&restoredLayer.Gloss==.2f&&restoredLayer.Metalness==.6f,"Portable patterns retain their recipe, placement, finish and independent pixels after source removal");
        var regenerated=PatternArtwork.Generate(restoredLayer.PatternArtwork!,workspace);check(FinishMaps.Read(regenerated).Pixels.SequenceEqual(FinishMaps.Read(restoredLayer.Asset).Pixels),"Restored recipe regenerates the exact portable artwork pixels");
        var reusable=ReusableArtwork.Save("Gradient badge",[restoredLayer],workspace);var opened=ReusableArtwork.Open(reusable,Path.Combine(temp,"pattern-group"));check(opened.Single().PatternArtwork==restoredLayer.PatternArtwork,"Reusable artwork groups preserve editable pattern recipes");
        reject(()=>new LayerDocument{Version=3,History=[new("Pattern",DateTimeOffset.UtcNow,[layer])]}.Validate(files:false),"Pattern recipes cannot be silently encoded as an older editor format");reject(()=>PatternArtwork.Render(options with {AlphaA=0,AlphaB=0},64),"Reject an entirely invisible pattern");reject(()=>PatternArtwork.Render(options with {Angle=float.NaN},64),"Reject non-finite pattern controls");reject(()=>PatternArtwork.Render(options with {Repeats=1000},64),"Reject excessive pattern density");reject(()=>PatternArtwork.Render(options with {ColorA="bad"},64),"Reject malformed pattern colors");reject(()=>PatternArtwork.Render(options with {Aspect=0},64),"Reject a zero-sized pattern aspect");reject(()=>PatternArtwork.Render(options with {Transition=0},64),"Reject a degenerate gradient transition");
        using var cancelled=new CancellationTokenSource();cancelled.Cancel();var stopped=false;try{PatternArtwork.Render(options,cancellation:cancelled.Token);}catch(OperationCanceledException){stopped=true;}check(stopped,"Pattern generation honors cancellation before producing an incomplete asset");
    }
}
